public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a visited array to keep track of the n-tersections that have been visited
    boolean[] visited = new boolean[n];

    // Set the starting n-tersection as visited
    visited[start[0]] = true;

    // Initialize a queue to traverse the maze
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);

    // Traverse the maze using Breadth-First Search (BFS)
    while (!queue.isEmpty()) {
        int[] current = queue.poll();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }

        // Iterate through the paths between adjacent n-tersections
        for (int[] path : paths) {
            // If the current n-tersection is adjacent to a n-tersection that has not been visited, add it to the queue and mark it as visited
            if (path[0] == current[0] && !visited[path[1]]) {
                queue.offer(path[1]);
                visited[path[1]] = true;
            }
        }
    }

    // If the maze has been fully traversed and the ending n-tersection has not been found, return "cannot be travelled"
    return "cannot be travelled";
}

